    {'cat': 'remark', 'text': 'De mon temps, le quadrille était une affaire sérieuse.', 'voice': 'char_hortense_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_hortense_gown_remark_17', 'whispered': False, 'nonverbal': False, 'gun': False, 'context': 'dance'},
